parameters.jsCode:
// Parse the AI response
const aiResponse = $input.item.json;
let aiText = '';
try {
  aiText = aiResponse.choices[0].message.content.trim();
} catch(e) {
  // Fallback if OpenAI call fails
  return [{
    json: {
      user_id: $('Set Fields').item.json.user_id,
      backend_webhook: $('Set Fields').item.json.backend_webhook,
      decision: 'pending',
      confidence: 0.5,
      reason: 'AI analysis failed - requires manual review',
      name: $('Set Fields').item.json.name,
      email: $('Set Fields').item.json.email,
    }
  }];
}

// Parse the JSON from AI
let parsed = {};
try {
  // Extract JSON from response (in case AI adds extra text)
  const jsonMatch = aiText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    parsed = { decision: 'rejected', confidence: 0.1, reason: 'Could not parse AI response' };
  }
} catch(e) {
  parsed = { decision: 'rejected', confidence: 0.1, reason: 'AI response parsing error' };
}

// Clamp confidence to 0-1
const confidence = Math.min(1.0, Math.max(0.0, parsed.confidence || 0.5));

// Threshold: approve if confidence >= 0.6
const decision = (confidence >= 0.6 && parsed.decision === 'approved') ? 'approved' : 'rejected';

return [{
  json: {
    user_id: $('Set Fields').item.json.user_id,
    backend_webhook: $('Set Fields').item.json.backend_webhook,
    name: $('Set Fields').item.json.name,
    email: $('Set Fields').item.json.email,
    decision: decision,
    confidence: confidence,
    reason: parsed.reason || 'Verified by AI',
    raw_ai_response: aiText,
  }
}];
